<template><view class="campaigns"><view class="card"><text class="heading">商城活动</text><text class="hint">秒杀、拼团与组合购按活动规则购买。价格、库存和限购以提交时确认结果为准。</text></view><view v-if="error" class="card">{{error}}</view><view v-if="!visibleRows.length&&!error" class="card">暂时没有进行中的活动。</view><view v-for="c in visibleRows" :key="c.id" class="card"><text class="heading">{{c.name}}</text><text>{{names[c.kind]}} · {{started(c)?'进行中':'尚未开始'}}</text><text v-if="c.config.firstOnly" class="hint">仅限首单；有待付款订单时请先处理。</text><text v-if="c.config.minimumTier" class="hint">{{minimumTierText(c)}}</text><text class="hint">{{formatDate(c.starts_at)}} 至 {{formatDate(c.ends_at)}}</text><view v-for="i in c.config.items" :key="i.productId" class="product"><image v-if="product(i.productId).image" :src="asset(product(i.productId).image)" mode="aspectFill"/><view>{{product(i.productId).name}} {{product(i.productId).spec}}<text v-if="soldCountText(product(i.productId).soldCount)" class="hint">{{soldCountText(product(i.productId).soldCount)}}</text><text v-if="['price','flash','group'].includes(c.kind)" class="hint">活动价 ¥{{money(i.price)}} / 件</text><text v-if="['combo','gift'].includes(c.kind)" class="hint">每份 {{i.quantity}} 件</text></view></view><view v-if="c.kind==='combo'">每套 ¥{{money(c.config.bundlePrice)}}，每人限 {{c.config.limit}} 套</view><view v-if="c.kind==='flash'">每人限 {{c.config.limit}} 件</view><view v-if="c.kind==='group'">{{c.config.people}} 人成团，{{c.config.hours}} 小时内完成；仅付款成功计入人数，未成团自动退款。</view><view v-if="c.kind==='gift'">商品优惠后满 ¥{{money(c.config.threshold)}} 赠送以上商品，缺货不替换。</view><view v-if="c.kind==='discount'">适用商品满 ¥{{money(c.config.threshold)}}，{{c.config.reduction?'减 ¥'+money(c.config.reduction):''}} {{c.config.payRate<10000?'或享 '+(c.config.payRate/1000)+' 折，择优使用':''}}</view><template v-if="['flash','group','combo'].includes(c.kind)"><view v-if="c.kind!=='group'">购买{{c.kind==='combo'?'套数':'件数'}}<input type="number" :value="quantities[c.id]||1" @input="quantities[c.id]=Number($event.detail.value)"/></view><button class="ui-button" :disabled="!started(c)" @click="buy(c)">{{c.kind==='group'?'我要开团':'购买这一份'}}</button><view v-for="g in c.groups||[]" :key="g.id" class="join"><text>已有 {{g.paid_people}} 人付款 / {{g.required_people}} 人 · {{formatDate(g.expires_at)}} 截止</text><button class="ui-button" @click="buy(c,g.id)">参加这一团</button></view></template><button class="ui-button" v-else @click="go(channel==='B'?'business':'category',{channel})">去选购商品</button></view></view></template>
<script>
import {request,asset,money,go} from '../services/shop'
import {soldCountText} from '../services/sold-count'
import {formatDate,beijingTime} from '../services/display'
import {serverNow} from '../services/server-clock'
export default {props:{channel:{default:'C'},campaignId:{default:''},refreshTick:{default:0}},watch:{refreshTick(){this.load()}},computed:{visibleRows(){return this.campaignId?this.rows.filter(c=>String(c.id)===String(this.campaignId)):this.rows}},data(){return{rows:[],quantities:{},products:[],error:'',names:{price:'活动价',discount:'满减满折',flash:'限时秒杀',group:'多人拼团',combo:'固定组合购',gift:'满额赠品'}}},mounted(){this.load()},methods:{soldCountText,asset,money,formatDate,go,minimumTierText(c){const scope=(c.channel||this.channel)==='B'?'采购等级':'会员等级';return c.minimumTierName?'需要'+c.minimumTierName+'及以上'+scope+'。':'需要达到第'+(Number(c.config.minimumTier)+1)+'档及以上'+scope+'。'},product(id){return this.products.find(p=>p.id===id)||{name:'商品暂不可售'}},started(c){return beijingTime(c.starts_at)<=serverNow()},async load(){try{this.error='';const [rows,data]=await Promise.all([request('/campaigns?channel='+this.channel),request('/bootstrap')]);this.rows=rows.map(c=>({...c,config:JSON.parse(c.config_json)}));this.products=data.products}catch(e){this.error=e.message}},buy(c,groupId=0){const uid=uni.getStorageSync('shop-owner');if(!uid){uni.setStorageSync('shop-return',{screen:'campaigns',query:{channel:this.channel}});go('login');return}uni.setStorageSync('shop-cart-'+uid+'-checkout',{channel:this.channel,campaignId:c.id,groupId,bundles:this.quantities[c.id]||1,items:c.config.items.map(i=>({id:i.productId,quantity:c.kind==='combo'?i.quantity*(this.quantities[c.id]||1):c.kind==='group'?1:this.quantities[c.id]||1})),requestKey:'campaign_'+Date.now()+'_'+Math.random().toString(36).slice(2)});go('checkout',{channel:this.channel})}}}
</script><style scoped>
@import '../styles/component-base.css';
.campaigns{padding:16px;font-size:16px}.card{background:var(--shop-surface, #fdfeff);padding:18px;border-radius:12px;margin-bottom:16px;line-height:1.9}.heading{font-size:21px;font-weight:bold;display:block}.hint{font-size:14px;color:var(--shop-ink, #28546c);display:block}.product{display:flex;align-items:center;gap:12px;margin:12px 0}.product image{width:76px;height:76px;border-radius:8px}button{margin-top:12px;background:var(--shop-accent, #c7e8f5);color:var(--shop-ink, #28546c);font-size:16px}.join{border-top:1px solid var(--shop-border, #d5e6ee);padding-top:12px;margin-top:14px}</style>
